package pe.edu.utec.labreserve.controller;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import pe.edu.utec.labreserve.config.UserPrincipal; import pe.edu.utec.labreserve.dto.request.CreateOrderRequestDto; import pe.edu.utec.labreserve.dto.response.*; import pe.edu.utec.labreserve.service.OrderService;
@RestController public class OrderController{private final OrderService service; public OrderController(OrderService service){this.service=service;} @PostMapping("/orders") public ResponseEntity<OrderResponseDto> create(@Valid @RequestBody CreateOrderRequestDto r,@AuthenticationPrincipal UserPrincipal user){return ResponseEntity.status(201).body(service.create(r,user));} @GetMapping("/my-orders") public PagedResponseDto<MyOrderResponseDto> mine(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size,@AuthenticationPrincipal UserPrincipal user){return service.myOrders(user,page,size);}}
